1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.plugin.variable.Out;
5	import net.officefloor.web.HttpHeaderParameter;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.samples.petclinic.mapper.OwnerMapper;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	
12	/**
13	 * First step of create-owner: honours the optional {@code Idempotency-Key} header. When a key has
14	 * already been seen (see {@link OwnerIdempotency}), responds {@code 200} with the originally
15	 * created owner and short-circuits — no duplicate is created. Otherwise it publishes the key for
16	 * {@link AssignOwnerIdempotencyKey} and takes the {@code create} flow into the normal pipeline.
17	 *
18	 * <p>Runs before the body is bound, so it never consumes the request body; the {@code create}
19	 * branch leads to {@link NormalizeOwnerAddress}, which binds it once for the pipeline.
20	 */
21	public class CheckIdempotencyKey {
22	
23	    @FunctionalInterface
24	    public interface CreateFlow {
25	        void create();
26	    }
27	
28	    public void service(@HttpHeaderParameter("Idempotency-Key") String key,
29	            OwnerRepository ownerRepository, OwnerMapper ownerMapper,
30	            Out<RequestIdempotencyKey> idempotencyKey, ObjectResponse<OwnerDto> response,
31	            @Flow("create") CreateFlow create) {
32	        Owner existing = OwnerIdempotency.findByKey(ownerRepository, key);
33	        if (existing != null) {
34	            response.send(ownerMapper.toOwnerDto(existing));
35	            return;
36	        }
37	        idempotencyKey.set(new RequestIdempotencyKey(key));
38	        create.create();
39	    }
40	}
