7	/**
8	 * Canonicalizes the create-owner address to its normalized form (see {@link OwnerAddresses})
9	 * and publishes the request body for the rest of the pipeline. Runs first so the normalized
10	 * address flows into the required-field check, the household comparisons, storage and the
11	 * response. Prefers the structured {@code addressLine1}/{@code addressLine2} fields when
12	 * supplied, falling back to the flat {@code address} for backward compatibility.
13	 *
14	 * <p>Binds the request body once for the pipeline; later steps read it via {@code @Val}.
15	 */
16	public class NormalizeOwnerAddress {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> body) {
19	        OwnerAddresses.normalize(request);
20	        body.set(request);
21	    }
22	}
