1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
8	
9	/**
10	 * The single duplicate check for create-owner, responding 409 via
11	 * {@link DuplicateOwnerException} on an <b>identity duplicate</b> — an existing owner with the same
12	 * derived {@code identityKey} (telephone, email and phonetic last name, see {@link OwnerIdentities}),
13	 * i.e. an exact resubmission of an existing owner.
14	 *
15	 * <p>Two owners sharing only a last name and postcode but giving different telephones no longer
16	 * collide here — telephone is part of the key — so they are admitted and instead flagged as a soft
17	 * duplicate ({@link FlagOwnerPossibleDuplicate}). Household co-membership is likewise admitted and
18	 * governed by the membership level ceiling ({@link AssignOwnerMembershipLevel}).
19	 *
20	 * <p>Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} so the request
21	 * telephone is already E.164 and its email lower-cased, and after {@link RequireOwnerEmailAllowed}
22	 * so a blocklisted email is rejected first.
23	 */
24	public class RequireUniqueIdentity {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateOwnerException {
28	        String identityKey = OwnerIdentities.key(request.getTelephone(), request.getEmail(),
29	                request.getLastName());
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isDeleted()) {
32	                continue; // a soft-deleted owner never blocks a new one
33	            }
34	            if (identityKey.equals(OwnerIdentities.of(existing))) {
35	                throw new DuplicateOwnerException(identityKey);
36	            }
37	        }
38	    }
39	}
