7	
8	/**
9	 * Rejects a create-owner request whose city already holds the maximum number of owners
10	 * ({@value #CAPACITY}), responding 409 via {@link CityAtCapacityException}. Cities are
11	 * compared exactly.
12	 */
13	public class RequireCityCapacity {
14	
15	    /** Maximum owners allowed per city; the request is rejected once this is reached. */
16	    static final int CAPACITY = 50;
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws CityAtCapacityException {
20	        String city = request.getCity();
21	        if (OwnerCities.countIn(ownerRepository, city) >= CAPACITY) {
22	            throw new CityAtCapacityException(city, CAPACITY);
23	        }
24	    }
25	}
