15	
16	    /** Owners in a city at or above which the approaching-capacity warning is raised. */
17	    static final int WARNING_THRESHOLD = 40;
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        long inCity = OwnerCities.countIn(ownerRepository, owner.getCity());
21	        owner.setCapacityWarning(inCity >= WARNING_THRESHOLD && inCity < RequireCityCapacity.CAPACITY);
22	    }
