1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns a new owner's {@code memberId} before it is saved. The id is
12	 * {@code <REGION><FY><HASH8><CHK>} (see {@link OwnerMemberIds}): the region derived from the owner's
13	 * postcode, the fiscal year of the registration date, a hash of their telephone and last name and a
14	 * Luhn check digit, so it is a stable function of the owner's own identity rather than a per-city
15	 * sequence. When that id collides with an existing owner's, it is de-duplicated by appending
16	 * {@code -<n>} (smallest {@code n} of 2 or more that is unique).
17	 */
18	public class AssignOwnerMemberId {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String base = OwnerMemberIds.forOwner(owner);
22	        Set<String> taken = new HashSet<>();
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (existing.getMemberId() != null) {
25	                taken.add(existing.getMemberId());
26	            }
27	        }
28	        owner.setMemberId(OwnerMemberIds.deduplicate(base, taken));
29	    }
30	}
