1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.OptionalInt;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.MembershipLevel;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Fixes the new owner's membership level at creation time, capped against their household: it may
12	 * exceed the highest effective level already held by an existing household member (one sharing this
13	 * owner's deterministic {@code householdId}, see {@link OwnerHouseholds}) by at most one. With no
14	 * existing household member no cap applies and the owner keeps its own derived level.
15	 *
16	 * <p>Runs after {@link AssignOwnerHouseholdSize} and {@link AssignOwnerNamesakeCount} — which set
17	 * the fields that feed {@link org.springframework.samples.petclinic.model.MembershipPoints} — and
18	 * before {@link SaveOwner}, so the recorded level reflects the household at creation time.
19	 */
20	public class AssignOwnerMembershipLevel {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        int level = MembershipLevel.of(owner);
24	        OptionalInt householdMax = householdMaxLevel(owner, ownerRepository);
25	        if (householdMax.isPresent()) {
26	            level = MembershipLevel.cappedToHousehold(level, householdMax.getAsInt());
27	        }
28	        owner.setMembershipLevel(level);
29	    }
