31	    /** The highest effective membership level among the new owner's existing household members. */
32	    private static OptionalInt householdMaxLevel(Owner owner, OwnerRepository ownerRepository) {
33	        String householdId = owner.getHouseholdId();
34	        if (householdId == null) {
35	            return OptionalInt.empty();
36	        }
37	        OptionalInt max = OptionalInt.empty();
38	        for (Owner existing : ownerRepository.findAll()) {
39	            if (householdId.equals(existing.getHouseholdId())) {
40	                int level = MembershipLevel.effective(existing);
41	                max = max.isPresent() ? OptionalInt.of(Math.max(max.getAsInt(), level)) : OptionalInt.of(level);
42	            }
43	        }
