2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.util.Soundex;
8	
9	/**
10	 * Flags a soft duplicate: an owner that passed the hard-duplicate check (see
11	 * {@link RequireUniqueIdentity}) but still looks like it may duplicate an existing one because it
12	 * shares that owner's postcode and phonetically-equal last name ({@link Soundex}) while resolving
13	 * to a different {@code identityKey} (see {@link OwnerIdentities}) — i.e. a different telephone or
14	 * email. Sets {@link Owner#getPossibleDuplicate() possibleDuplicate} true and
15	 * {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} to the matching owner's id; otherwise
16	 * leaves the flag false and no reference.
17	 *
18	 * <p>A declared household member — one that opted in with {@code sharesHousehold} to join an
19	 * existing (lastName, postcode) household — is never flagged: a declared member is not a
20	 * suspected duplicate.
21	 *
22	 * <p>Runs before {@link SaveOwner} so it compares only against already-stored owners and never
23	 * itself. When several owners match, the lowest id is chosen for a deterministic reference.
24	 */
25	public class FlagOwnerPossibleDuplicate {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
28	        Integer matchId = null;
29	        boolean declaredMember = Boolean.TRUE.equals(request.getSharesHousehold());
30	        if (!declaredMember && owner.getPostcode() != null) {
31	            String identityKey = OwnerIdentities.of(owner);
32	            String soundex = Soundex.encode(owner.getLastName());
33	            for (Owner existing : ownerRepository.findAll()) {
34	                if (owner.getPostcode().equals(existing.getPostcode())
35	                        && soundex.equals(Soundex.encode(existing.getLastName()))
36	                        && !identityKey.equals(OwnerIdentities.of(existing))
37	                        && (matchId == null || existing.getId() < matchId)) {
38	                    matchId = existing.getId();
39	                }
40	            }
41	        }
42	        owner.setPossibleDuplicate(matchId != null);
43	        owner.setPossibleDuplicateOf(matchId);
44	    }
45	}
