27	        problemDetail.setTitle(ex.getClass().getSimpleName());
28	        problemDetail.setDetail(detail);
29	        problemDetail.setProperty("timestamp", Instant.now());
30	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
31	        return problemDetail;
32	    }
