    private static final ObjectMapper JSON = new ObjectMapper();
    public void service(@Val Owner owner, OwnerCreatedEventSequence sequence) {
        OwnerCreatedEvent event = new OwnerCreatedEvent(sequence.next(), owner.getId(),
